'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shapes={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3z',learn:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3z M12 6v15',progress:'M4 20V12m8 8V4m8 16V8',saved:'M6 3h12v18l-6-4-6 4z',tools:'m14 6 4 4M5 20l-2-2 9-9a6 6 0 0 1 8-7l-4 4 2 2 4-4a6 6 0 0 1-7 8z',wallet:'M3 6h17v14H3z M3 6l14-3v3 M15 11h6v5h-6z M17 13h1',chef:'M6 12C-1 11 2 3 7 5c1-5 9-5 10 0 5-2 8 6 1 7v9H6z M6 17h12',car:'m4 8 2-5h12l2 5 M3 8h18v10H3z M6 18v3m12-3v3 M6 12h2m8 0h2',shield:'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6z m-5 10 3 3 6-6',briefcase:'M3 7h18v14H3z M8 7V3h8v4 M3 12c6 4 12 4 18 0 M10 13h4v4h-4z',search:'m16 16 5 5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',arrow:'M4 12h16m-6-6 6 6-6 6',clock:'M12 7v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'m5 12 4 4L19 6',user:'M20 21v-3c0-5-16-5-16 0v3 M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${shapes[name]||shapes.learn}"/></svg>`;
let S={user:null,csrf:'',categories:[],lessons:[],paths:[],settings:{},saved:[],progress:[],userPaths:[],admin:null};
let renderVersion=0;
async function api(url,method='GET',body){const r=await fetch('/api/'+url,{method,headers:{'Content-Type':'application/json','X-CSRF-Token':S.csrf},body:body===undefined?undefined:JSON.stringify(body)});let d;try{d=await r.json()}catch{throw Error('The server could not complete this request.')}if(!r.ok)throw Error(d.error||'Something went wrong. Please try again.');return d}
function toast(t){const el=$('#toast');el.textContent=t;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',4500)}
async function refresh(){const c=await api('catalog');Object.assign(S,c);if(S.user){const l=await api('library');S.saved=l.saved.map(x=>x.lesson_id);S.progress=l.progress;S.userPaths=l.paths}else{S.saved=[];S.progress=[];S.userPaths=[]}document.documentElement.style.setProperty('--primary',/^#[a-f\d]{6}$/i.test(S.settings.primary)?S.settings.primary:'#4f46e5')}
function go(path){history.pushState({},'',path);render();window.scrollTo(0,0)}
const navs=[['/','home','Home'],['/learn','learn','Learn'],['/progress','progress','My Progress'],['/saved','saved','Saved'],['/tools','tools','Tools']];
function chrome(){const path=location.pathname;const links=navs.map(([url,ic,label])=>`<a href="${url}" class="${path===url?'active':''}">${label}</a>`).join('');$('#header').innerHTML=`<a href="/" class="brand" aria-label="How2 home"><span>h₂</span>how<em>2</em></a><nav aria-label="Main navigation">${links}</nav><div class="header-actions"><a href="/learn?focus=search" class="icon-btn search-action" aria-label="Search lessons">${icon('search')}</a>${S.user?`<a class="icon-btn" href="/profile" aria-label="Your profile">${icon('user')}</a>${['owner','content'].includes(S.user.role)?'<a class="text-link" href="/admin">Admin</a>':''}`:'<a href="/login" class="button">Log in / Sign up '+icon('arrow')+'</a>'}</div>`;
$('#footer').innerHTML=`<div><a href="/" class="brand">how<em>2</em></a><p>Life doesn't come with instructions. Now it does.</p></div><div class="links">${[['About How2','about'],['Contact','contact'],['Privacy','privacy'],['Terms','terms'],['Help Center','help']].map(([a,b])=>`<a href="/${b}">${a}</a>`).join('')}<a href="/suggest">Suggest a Lesson</a><a href="/admin/login">Admin</a></div><div class="bottom-nav" aria-label="Mobile navigation">${navs.map(([u,i,l])=>`<a href="${u}" class="${path===u?'active':''}">${icon(i)}${l}</a>`).join('')}</div>`}
const category=id=>S.categories.find(c=>c.id===id)||{name:'Life skills',color:'#e8eee1',icon:'learn'};
function catCards(){return `<div class="category-grid">${S.categories.map(c=>`<a href="/category/${c.id}" class="category"><span class="cat-icon" style="background:${/^#[\da-f]{6}$/i.test(c.color)?c.color:'#e8eee1'}">${icon(c.icon)}</span><div><h3>${esc(c.name)}</h3><p>${esc(c.description)}</p></div><span class="arrow">↗</span></a>`).join('')}</div>`}
function card(l){const c=category(l.category_id);return `<article class="lesson-card"><a href="/lesson/${l.id}" class="lesson-art" style="background:${/^#[\da-f]{6}$/i.test(c.color)?c.color:'#e8eee1'}" aria-label="Read ${esc(l.title)}"><span class="art-label">THE EVERYDAY ESSENTIALS</span>${icon(c.icon)}</a><div class="card-content"><span class="tag">${esc(c.name)}</span><h3><a href="/lesson/${l.id}">${esc(l.title)}</a></h3><p>${esc(l.description)}</p><div class="meta"><span>${icon('clock')}${l.minutes} min</span><span>◒ &nbsp;${esc(l.difficulty)}</span></div><div class="card-bottom"><a href="/lesson/${l.id}">Start learning &nbsp; ↗</a><button class="icon-btn ${S.saved.includes(l.id)?'saved':''}" data-save="${l.id}" aria-label="${S.saved.includes(l.id)?'Unsave':'Save'} ${esc(l.title)}" aria-pressed="${S.saved.includes(l.id)}">${icon('saved')}</button></div></div></article>`}
function searchForm(value=''){return `<form id="search-form" class="search" role="search">${icon('search')}<input id="search" name="q" aria-label="Search lessons" placeholder="How do I budget, cook, fix something...?" value="${esc(value)}"><button class="button" type="submit">Search ${icon('arrow')}</button></form>`}
function home(){const f=Array.isArray(S.settings.featured)?S.settings.featured:[];const lessons=f.map(id=>S.lessons.find(l=>l.id===Number(id))).filter(Boolean);return `${S.settings.announcement?`<div class="notice">${esc(S.settings.announcement)}</div>`:''}<div class="layout"><section class="hero"><div><div class="eyebrow">A little learning. A lot more living.</div><h1>${esc(S.settings.headline).replace('learn today?','<em>learn today?</em>')}</h1><p>${esc(S.settings.description)}</p>${searchForm()}<div class="hero-note">${icon('check')} Real-life skills. At your pace. Always free to explore.</div></div><div class="illustration" role="img" aria-label="An illustrated guidebook to everyday life skills">${S.settings.image_url&&safeURL(S.settings.image_url)?`<img class="homepage-image" src="${esc(safeURL(S.settings.image_url))}" alt="${esc(S.settings.image_alt||'')}">`:'<div class="orb"></div>'}<span class="spark">✳</span><div class="book"><small>THE UNOFFICIAL GUIDE TO</small><strong>life,<br>figured<br>out.</strong><p>A little help from how2 ↗</p></div><div class="float-card one">${icon('wallet')}Money confidence</div><div class="float-card two">${icon('chef')}Your first real meal</div><span class="spark b">✧</span></div></section><section class="section"><div class="section-head"><div><h2>Big life stuff. Small, simple steps.</h2><p>Pick a skill. Build your confidence. You've got this.</p></div><a href="/learn" class="text-link">Explore all categories ↗</a></div>${catCards()}</section><section class="section"><div class="section-head"><div><h2>Start with the essentials</h2><p>A few good places to begin your next chapter.</p></div><a href="${['/learn','/tools','/onboarding','/progress'].includes(S.settings.button_destination)?S.settings.button_destination:'/learn'}" class="text-link">${esc(S.settings.button_label||'View all lessons')} ↗</a></div><div class="lesson-grid">${lessons.map(card).join('')}</div></section><section class="journey"><div class="journey-icon">✳</div><div><span class="eyebrow">YOUR LIFE. YOUR LEARNING.</span><h2>${S.user?'Continue your journey':"Let's find out what you want to learn."}</h2><p>${S.user?'Pick up where you left off, or take one small step toward a new goal.':'A first paycheck? A place of your own? Start with what matters to you.'}</p></div><a class="button" href="${S.user?'/progress':'/onboarding'}">${S.user?'My progress':'Find my starting point'} ${icon('arrow')}</a></section>${S.user?recent():''}${recommendedPaths()}</div>`}
function recent(){const items=S.progress.filter(p=>!p.completed).map(p=>S.lessons.find(l=>l.id===p.lesson_id)).filter(Boolean).slice(0,3);return items.length?`<section class="section"><h2>Pick up where you left off</h2><div class="lesson-grid">${items.map(card).join('')}</div></section>`:''}
function libraryPage(catId){const c=catId?category(catId):null;return `<div class="layout"><div class="page-head"><span class="eyebrow">A little know-how goes a long way</span><h1>${c?esc(c.name):'Explore life skills'}</h1><p>${c?esc(c.description):'Useful lessons for whatever life has in store.'}</p></div>${searchForm(new URLSearchParams(location.search).get('q')||'')}<div class="filters"><select id="category-filter" aria-label="Filter by category"><option value="">All categories</option>${S.categories.map(x=>`<option value="${x.id}" ${x.id===catId?'selected':''}>${esc(x.name)}</option>`).join('')}</select><select id="difficulty-filter" aria-label="Filter by difficulty"><option value="">All levels</option><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select><select id="duration-filter" aria-label="Filter by duration"><option value="">Any length</option><option value="10">10 minutes or less</option><option value="20">20 minutes or less</option></select><select id="sort-filter" aria-label="Sort lessons"><option value="default">Essentials first</option><option value="recent">Recently added</option><option value="short">Shortest first</option></select></div><p id="result-count" class="muted"></p><div id="results" class="lesson-grid mb"></div>${c?`<section class="section"><h2>Put it into practice</h2><p>Turn what you've learned into a plan with a practical tool.</p><a class="button" href="/tools">Explore tools ${icon('arrow')}</a></section>`:''}</div>`}
function filterLessons(){let q=$('#search')?.value.toLowerCase().trim()||'',cat=$('#category-filter')?.value||'',dif=$('#difficulty-filter')?.value||'',dur=Number($('#duration-filter')?.value||0);let ls=S.lessons.filter(l=>(!q||`${l.title} ${l.description} ${l.keywords} ${category(l.category_id).name}`.toLowerCase().includes(q))&&(!cat||l.category_id===Number(cat))&&(!dif||l.difficulty===dif)&&(!dur||l.minutes<=dur));if($('#sort-filter')?.value==='recent')ls.sort((a,b)=>b.id-a.id);if($('#sort-filter')?.value==='short')ls.sort((a,b)=>a.minutes-b.minutes);$('#result-count').textContent=`${ls.length} lesson${ls.length===1?'':'s'}`;$('#results').innerHTML=ls.length?ls.map(card).join(''):`<div class="empty wide"><h2>We couldn't find that lesson yet.</h2><p>Want to suggest it?</p><a class="button" href="/suggest">Suggest a lesson</a></div>`}
function safeURL(value){try{const u=new URL(value,location.origin);return u.protocol==='https:'||u.origin===location.origin?u.href:null}catch{return null}}
function inlineContent(t){const pattern=/!\[([^\]]*)\]\(([^\s)]+)\)|\[([^\]]+)\]\(([^\s)]+)\)|\*\*(.+?)\*\*/g;let out='',end=0;for(const m of t.matchAll(pattern)){out+=esc(t.slice(end,m.index));if(m[1]!==undefined){const url=safeURL(m[2]);out+=url?`<img class="lesson-image" src="${esc(url)}" alt="${esc(m[1])}" loading="lazy">`:esc(m[0])}else if(m[3]!==undefined){const url=safeURL(m[4]);out+=url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(m[3])}</a>`:esc(m[0])}else out+=`<strong>${esc(m[5])}</strong>`;end=m.index+m[0].length}return out+esc(t.slice(end))}
function formatContent(t){return String(t).split(/\n\s*\n/).map(block=>{if(block.startsWith('## '))return `<h2>${inlineContent(block.slice(3))}</h2>`;if(block.startsWith('### '))return `<h3>${inlineContent(block.slice(4))}</h3>`;if(block.split('\n').every(line=>line.startsWith('- ')))return '<ul>'+block.split('\n').map(line=>`<li>${inlineContent(line.slice(2))}</li>`).join('')+'</ul>';if(block.startsWith('@video ')){const url=safeURL(block.slice(7).trim());try{const parsed=new URL(url);if(parsed.hostname==='www.youtube-nocookie.com'&&/^\/embed\/[a-zA-Z0-9_-]+$/.test(parsed.pathname))return `<iframe class="lesson-video" src="${esc(url)}" title="Lesson video" loading="lazy" allowfullscreen></iframe>`}catch{}return '<p>Video address is not supported. Use a reviewed youtube-nocookie.com/embed/ link.</p>'}return `<p>${inlineContent(block).replace(/\n/g,'<br>')}</p>`}).join('')}
function lessonPage(id){const l=S.lessons.find(l=>l.id===id);if(!l)return notFound();const c=category(l.category_id),done=S.progress.some(p=>p.lesson_id===id&&p.completed);let quiz=[];try{quiz=JSON.parse(l.quiz)}catch{}return `<div class="layout"><article class="reader"><a class="text-link" href="/category/${c.id}">← ${esc(c.name)}</a><h1>${esc(l.title)}</h1><p class="intro">${esc(l.description)}</p><div class="flex"><span class="pill">${icon('clock')} ${l.minutes} minutes</span><span class="pill">${esc(l.difficulty)}</span><button class="secondary" data-save="${id}">${S.saved.includes(id)?'Saved ✓':'Save lesson'}</button></div><div class="reader-body">${formatContent(l.content)}${l.example?`<div class="example"><h3>A real-life example</h3><p>${esc(l.example)}</p></div>`:''}<div class="source">Content date: ${esc(l.review_date||'Not specified')}. ${l.needs_review?'Editorial review pending; this content has not been expert-reviewed.':''}<br>References: ${String(l.sources||'').split('\n').filter(Boolean).map(s=>/^https:\/\//.test(s)?`<a href="${esc(s)}" target="_blank" rel="noopener noreferrer">${esc(s)}</a>`:esc(s)).join('<br>')}</div>${quiz.map((q,i)=>`<form class="quiz" data-quiz="${i}" data-lesson="${id}"><h3>Quick knowledge check ${quiz.length>1?i+1:''}</h3><p>${esc(q.question)}</p>${q.options.map((o,j)=>`<label><input type="radio" name="answer" value="${j}" required> ${esc(o)}</label>`).join('')}<button class="secondary" type="submit">Check answer</button><output aria-live="polite"></output></form>`).join('')}<div class="flex" style="margin-top:30px"><button class="primary" data-complete="${id}" data-done="${done}">${done?'Completed ✓ — mark incomplete':'Mark lesson complete '+icon('check')}</button><a class="text-link" href="/learn">Keep exploring ↗</a></div><p class="muted" style="margin-top:15px">${S.user?'Your progress is private and saved to your account.':'Sign in to save your progress across visits.'}</p><a class="text-link" href="/suggest?type=Error%20report&lesson=${id}">Report an issue with this lesson</a></div></article></div>`}
function savedPage(){const ls=S.lessons.filter(l=>S.saved.includes(l.id));return `<div class="layout"><div class="page-head"><h1>Your little library</h1><p>Good advice, kept close. Find your saved lessons here.</p></div>${!S.user?authPrompt('Sign in to keep your saved lessons in one place.'):ls.length?S.categories.map(c=>{const group=ls.filter(l=>l.category_id===c.id);return group.length?`<section class="section"><h2>${esc(c.name)}</h2><div class="lesson-grid">${group.map(card).join('')}</div></section>`:''}).join(''):'<div class="empty"><h2>Nothing saved yet.</h2><p>Explore lessons and bookmark anything you want to revisit.</p><a class="button" href="/learn">Explore lessons</a></div>'}</div>`}
function authPrompt(msg){return `<div class="empty"><h2>Make your learning your own.</h2><p>${esc(msg)}</p><a class="button" href="/login">Log in / Sign up</a></div>`}
function progressPage(){if(!S.user)return `<div class="layout"><div class="page-head"><h1>My progress</h1></div>${authPrompt('Create a free account to track the steps you take.')}</div>`;const valid=S.progress.filter(p=>S.lessons.some(l=>l.id===p.lesson_id)),completed=valid.filter(p=>p.completed).length,cats=new Set(valid.map(p=>S.lessons.find(l=>l.id===p.lesson_id).category_id));let prefs={};try{prefs=JSON.parse(S.user.preferences)}catch{}return `<div class="layout"><div class="page-head"><span class="eyebrow">ONE STEP AT A TIME</span><h1>Look how far you're going, ${esc(S.user.name)}.</h1><p>Your pace. Your goals. Every small step counts.</p></div><div class="stats"><div class="stat"><strong>${completed}</strong><span>Lessons completed</span></div><div class="stat"><strong>${valid.length-completed}</strong><span>In progress</span></div><div class="stat"><strong>${cats.size}</strong><span>Categories explored</span></div></div>${prefs.goal?`<p class="example">Your goal: ${esc(prefs.goal)}</p>`:''}${recent()}<section class="section"><h2>Your learning paths</h2><p class="muted">A little structure for your next chapter.</p>${S.paths.map(p=>{const ids=JSON.parse(p.lessons).filter(id=>S.lessons.some(l=>l.id===id)),count=ids.filter(id=>S.progress.some(x=>x.lesson_id===id&&x.completed)).length,state=S.userPaths.find(x=>x.path_id===p.id)?.state;return `<article class="path"><div class="flex"><h3>${esc(p.name)}</h3>${state?`<span class="badge">${state==='paused'?'Paused':'Active'}</span>`:''}</div><p class="muted">${esc(p.description)}</p><progress value="${count}" max="${Math.max(ids.length,1)}" aria-label="${esc(p.name)} completion"></progress><p class="muted">${count} of ${ids.length} lessons complete</p><ol>${ids.map(id=>{const l=S.lessons.find(l=>l.id===id);return `<li><a href="/lesson/${id}">${esc(l.title)}</a> ${S.progress.some(x=>x.lesson_id===id&&x.completed)?'✓':''}</li>`}).join('')}</ol><button class="secondary" data-path="${p.id}" data-state="${state==='active'?'paused':'active'}">${state==='active'?'Pause path':state==='paused'?'Resume path':'Start path'}</button></article>`}).join('')}</section>${completed?`<p class="example">${completed>=5?'✦ Five lessons completed. A solid foundation!':'✦ First steps taken. You completed your first lesson!'}</p>`:''}<a class="text-link" href="/onboarding">Update my learning goals ↗</a><section class="section"><h2>Completed lessons</h2><div class="lesson-grid">${valid.filter(p=>p.completed).map(p=>card(S.lessons.find(l=>l.id===p.lesson_id))).join('')||'<p class="muted">Your completed lessons will appear here when you mark them complete.</p>'}</div></section></div>`}
const field=(label,name,type='text',value='',extra='')=>`<label class="field">${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
function toolsPage(){return `<div class="layout"><div class="page-head"><span class="eyebrow">LESS GUESSWORK. MORE GAME PLAN.</span><h1>A little help with the numbers.</h1><p>Simple tools for real-life decisions. No bank connection needed. Your entries stay in this page.</p></div><div class="tool-grid"><form class="panel calc" data-tool="budget"><h2>Monthly budget</h2><p>See where your money goes, and make room for what matters.</p>${[['Monthly take-home income','income'],['Housing','housing'],['Food','food'],['Transportation','transport'],['Utilities','utilities'],['Other expenses','other'],['Savings goal per month','savings']].map(([l,n])=>field(l+' ($)',n,'number','0','min="0" step="0.01" required')).join('')}<div class="result" aria-live="polite"></div></form><div><form class="panel calc mb" data-tool="savings"><h2>Savings goal</h2><p>Give your next big thing a realistic timeline. Interest is not included.</p>${[['Savings goal','goal'],['Current savings','current'],['Monthly contribution','monthly']].map(([l,n])=>field(l+' ($)',n,'number','0','min="0" step="0.01" required')).join('')}<div class="result" aria-live="polite"></div></form><form class="panel calc" data-tool="apartment"><h2>First apartment budget</h2><p>Estimate monthly costs. Deposits, moving costs, and other one-time expenses are additional.</p>${[['Rent','rent'],['Utilities','utilities'],['Groceries','groceries'],['Transportation','transport'],['Internet','internet'],['Other recurring costs','other']].map(([l,n])=>field(l+' ($)',n,'number','0','min="0" step="0.01" required')).join('')}<div class="result" aria-live="polite"></div></form></div></div>${mealPlanner()}</div>`}
function calculate(form){const v=Object.fromEntries([...new FormData(form)].map(([k,v])=>[k,Number(v)])),out=form.querySelector('.result');if(Object.values(v).some(x=>!Number.isFinite(x)||x<0)){out.textContent='Enter valid amounts of zero or more.';return}const money=n=>n.toLocaleString('en-US',{style:'currency',currency:'USD'});if(form.dataset.tool==='budget'){const exp=v.housing+v.food+v.transport+v.utilities+v.other,available=v.income-exp,remaining=available-v.savings;out.innerHTML=`Income: ${money(v.income)}<br>Expenses: ${money(exp)}<br>Available before savings: ${money(available)}<br>Planned savings: ${money(v.savings)}<strong>${money(remaining)}</strong>Remaining after your savings goal${remaining<0?'<br>Your plan exceeds your income. Adjust expenses or the savings target.':''}`}else if(form.dataset.tool==='savings'){const left=Math.max(0,v.goal-v.current);out.innerHTML=left===0?'<strong>Goal reached!</strong>':v.monthly===0?'Add a monthly contribution to estimate your timeline.':`<strong>${Math.ceil(left/v.monthly)} months</strong>to save the remaining ${money(left)} (without interest).`}else out.innerHTML=`Estimated monthly cost<strong>${money(Object.values(v).reduce((a,b)=>a+b,0))}</strong>`}
function loginPage(signup=false,admin=false){return `<div class="layout"><form class="auth panel" id="auth-form" data-mode="${signup?'signup':'login'}" data-admin="${admin}"><span class="eyebrow">${admin?'HOW2 ADMIN':'YOUR NEXT CHAPTER'}</span><h1>${signup?'A little more independent.':admin?'Welcome back, admin.':'Good to see you.'}</h1><p class="muted">${signup?'Create a free account to save lessons and track your learning.':admin?'Sign in with your individual administrator account.':'Pick up right where you left off.'}</p>${signup?field('First name or nickname','name','text','','required autocomplete="given-name" maxlength="80"'):''}${field('Email','email','email','','required autocomplete="email" maxlength="254"')}${field('Password','password','password','','required autocomplete="'+(signup?'new-password':'current-password')+'" '+(signup?'minlength="12"':''))}${signup?'<p class="muted">Use at least 12 characters. We only ask for what your account needs. By signing up, you agree to our <a href="/terms">terms</a> and <a href="/privacy">privacy policy</a>.</p>':''}<div class="form-error" role="alert"></div><button class="button" type="submit">${signup?'Create account':'Sign in'} ${icon('arrow')}</button><p class="muted" style="margin-top:18px">${signup?'Already have an account? <a href="/login">Sign in</a>':admin?'Need access or a password reset? Contact the environment owner.':'New here? <a href="/signup">Create a free account</a>'}</p>${!signup?'<a class="text-link" href="/help">Forgot your password?</a>':''}</form></div>`}
function onboarding(){return `<div class="layout"><form id="onboarding-form" class="auth panel"><span class="eyebrow">START WITH WHAT MATTERS</span><h1>What's your next chapter?</h1><p class="muted">Entirely optional. Explore first, or choose a starting point. No exact birth date needed.</p><label class="field">Age group (optional)<select name="age"><option value="">Prefer not to say</option><option>13–17</option><option>18–25</option><option>26+</option></select></label><label class="field">What would you like to learn?<select name="interest">${S.categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label class="field">Your current goal<select name="goal"><option>Feel more independent</option><option>Manage my first paycheck</option><option>Move into my own place</option><option>Find my first job</option></select></label><label class="field">How do you like to learn?<select name="format"><option>Written guides</option><option>Quizzes</option><option>Checklists</option></select></label><button class="button" type="submit">Find my starting point ${icon('arrow')}</button><p><a class="text-link" href="/learn">I'll explore on my own</a></p></form></div>`}
function profilePage(){if(!S.user)return loginPage();return `<div class="layout"><div class="auth panel"><h1>Your account</h1><p class="muted">${esc(S.user.email)} · ${esc(S.user.role)}</p><form id="profile-form">${field('Display name','name','text',S.user.name,'required maxlength="80"')}<button class="button">Save profile</button></form><hr><form id="password-form"><h3>Change password</h3>${field('Current password','current_password','password','','required autocomplete="current-password"')}${field('New password','password','password','','required minlength="12" autocomplete="new-password"')}<button class="secondary">Update password</button></form><p><a class="text-link" href="/onboarding">Learning interests and goals ↗</a></p><div class="flex"><button class="secondary" data-logout>Sign out</button><button class="secondary" data-delete-account>Delete account</button></div></div></div>`}
function feedbackPage(){const params=new URLSearchParams(location.search);return `<div class="layout"><form class="auth panel" id="feedback-form"><span class="eyebrow">HELP SHAPE HOW2</span><h1>What should we know?</h1><p class="muted">Suggest a lesson, report an error, or share an idea. Please don't include private or financial information.</p><label class="field">Type<select name="type">${['Lesson request','Error report','Feature request','General feedback'].map(t=>`<option ${params.get('type')===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Message<textarea name="message" required minlength="10" maxlength="4000"></textarea></label><input name="lesson_id" type="hidden" value="${esc(params.get('lesson')||'')}"><button class="button" type="submit">Send feedback ${icon('arrow')}</button><div class="form-error" role="alert"></div></form></div>`}
const info={about:['A little know-how changes everything.','How2 helps you learn everyday skills that can make life feel more manageable. Start with a practical guide, try a tool, and build confidence at your own pace. Our initial lessons include reference links and clear review status. They have not been expert-reviewed.'],privacy:['Your learning is personal.','This development version stores account email, display name, password hashes, saved lessons, progress, and optional learning preferences in its local database. Session cookies keep you signed in. We do not use advertising trackers or connect to bank accounts. Administrators can manage content and account roles; learning activity is accessed through your own account. Avoid submitting sensitive information in feedback. You can delete your account from your profile. Database backups require a separate retention policy before production use.'],terms:['A guide, not a guarantee.','How2 provides general educational information. It is not personalized financial, legal, medical, insurance, or repair advice. Rules vary by location and circumstances. Read original references and consult qualified professionals where needed. Do not attempt unsafe repairs. This is an early development version; production terms and policies need owner review before public launch.'],help:['A little help getting started.','Explore public lessons without an account. Sign up to bookmark lessons and record progress. Completion is always your choice. Use Tools for budget and savings calculations. For a password reset, contact the environment operator, who can reset an account using the secure reset-password command. Email-based recovery is not configured in this development version.'],contact:['We’re listening.','Use the feedback form for questions, lesson ideas, and issues. Submissions are available to the administrators in the Feedback dashboard. No public support email has been configured.']};
function infoPage(k){return `<div class="layout"><article class="reader"><span class="eyebrow">HOW2 / ${esc(k)}</span><h1>${info[k][0]}</h1><div class="reader-body"><p>${info[k][1]}</p><a class="button" href="/suggest">Send feedback ${icon('arrow')}</a></div></article></div>`}
function notFound(){return '<div class="layout"><div class="empty"><h1>That page isn’t here.</h1><p>It may be unpublished, or the link may have changed.</p><a class="button" href="/learn">Explore lessons</a></div></div>'}
const adminSections=['Dashboard','Lessons','Categories','Learning Paths','Tools','Users','Feedback','Settings','Activity'];
function adminPage(section='dashboard'){const a=S.admin;if(!S.user||!['owner','content'].includes(S.user.role))return S.user?'<div class="layout"><div class="empty"><h1>Administrator access required.</h1><a href="/" class="button">Back home</a></div></div>':loginPage(false,true);if(!a)return '<p class="loading">Loading your workspace…</p>';let content='';
if(section==='dashboard')content=`<span class="eyebrow">YOUR CONTENT WORKSPACE</span><h1>Welcome to How2 Admin</h1><p class="muted">A little knowledge, ready to make a big difference.</p><div class="stats"><div class="stat"><strong>${a.lessons.filter(l=>l.status==='published').length}</strong><span>Published lessons</span></div><div class="stat"><strong>${a.lessons.filter(l=>l.status==='draft').length}</strong><span>Draft lessons</span></div><div class="stat"><strong>${a.feedback.filter(f=>f.status==='New').length}</strong><span>New submissions</span></div></div><p>${a.categories.length} categories · ${a.lessons.filter(l=>l.needs_review).length} lessons needing editorial review</p><a class="button" href="/admin/lessons/new">+ Add new lesson</a><section class="section"><h2>Recently edited</h2>${adminTable(a.lessons.slice(0,5),'lessons')}</section>`;
if(section==='lessons')content=`<div class="section-head"><h1>Lessons</h1><a class="button" href="/admin/lessons/new">+ Add new lesson</a></div>${adminTable(a.lessons,'lessons')}`;
if(section==='categories')content=`<div class="section-head"><h1>Categories</h1><a class="button" href="/admin/categories/new">+ Add category</a></div>${adminTable(a.categories,'categories')}`;
if(section==='learning-paths')content=`<div class="section-head"><h1>Learning paths</h1><a class="button" href="/admin/paths/new">+ Add learning path</a></div>${adminTable(a.paths,'paths')}`;
if(section==='tools')content=`<div class="section-head"><h1>Recipe library</h1><a href="/admin/recipes/new" class="button">+ Add recipe</a></div><p class="muted">Only recipes you actually review and publish are used by the meal planner. No current grocery prices are claimed.</p>${adminTable(a.recipes,'recipes')}`;
if(section==='feedback')content=`<h1>Feedback & lesson requests</h1>${a.feedback.length?`<div class="table-wrap"><table><thead><tr><th>Date / type</th><th>Message</th><th>Status</th></tr></thead><tbody>${a.feedback.map(f=>`<tr><td>${esc(f.date)}<br>${esc(f.type)}</td><td>${esc(f.message)}${f.lesson_id?`<br>Lesson #${f.lesson_id}`:''}</td><td><select data-feedback="${f.id}" aria-label="Status for feedback ${f.id}">${['New','Under Review','Planned','Resolved','Archived'].map(x=>`<option ${x===f.status?'selected':''}>${x}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">No feedback submitted yet.</p>'}`;
if(section==='users')content=`<h1>People & permissions</h1>${S.user.role==='owner'?`<p class="muted">Users register individually. Grant Content Admin to your partner’s account, or use the secure create-admin command. No shared passwords.</p><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th></tr></thead><tbody>${a.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td><select data-role="${u.id}" aria-label="Role for ${esc(u.name)}">${[['user','Learner'],['content','Content Admin'],['owner','Owner Admin']].map(([v,l])=>`<option value="${v}" ${u.role===v?'selected':''}>${l}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">Only the owner can manage account permissions.</p>'}`;
if(section==='activity')content=`<h1>Activity log</h1>${a.activity.length?`<div class="table-wrap"><table><thead><tr><th>When</th><th>Action</th><th>Administrator</th></tr></thead><tbody>${a.activity.map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.action)}</td><td>${esc(x.name||'Deleted account')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">Content changes will appear here.</p>'}`;
if(section==='settings'){const s=a.settings;content=`<h1>Homepage editor</h1><p class="muted">Preview your changes, then publish them to the homepage immediately.</p><form id="settings-form" class="panel">${field('Homepage headline','headline','text',s.headline,'required')}${field('Homepage description','description','text',s.description,'required')}${field('Primary brand color','primary','color',s.primary)}${field('Announcement (leave blank to hide)','announcement','text',s.announcement)}${field('Homepage image URL (optional HTTPS address)','image_url','url',s.image_url||'')}${field('Homepage image description','image_alt','text',s.image_alt||'')}<fieldset class="field"><legend>Featured lessons</legend>${a.lessons.filter(l=>l.status==='published').map(l=>`<label class="check-row"><input type="checkbox" name="featured" value="${l.id}" ${(s.featured||[]).includes(l.id)?'checked':''}>${esc(l.title)}</label>`).join('')}</fieldset><fieldset class="field"><legend>Recommended learning paths</legend>${a.paths.filter(p=>p.status==='published').map(p=>`<label class="check-row"><input type="checkbox" name="recommended_paths" value="${p.id}" ${(s.recommended_paths||[]).includes(p.id)?'checked':''}>${esc(p.name)}</label>`).join('')}</fieldset>${field('Homepage button label','button_label','text',s.button_label||'Explore all lessons')}<label class="field">Button destination<select name="button_destination">${['/learn','/tools','/onboarding','/progress'].map(x=>`<option ${s.button_destination===x?'selected':''}>${x}</option>`).join('')}</select></label><p class="muted">Change category order, icons, and accent colors in Categories. Provide an optional image URL and descriptive alternative text. Images should be licensed for your use.</p><div class="flex"><button type="button" class="secondary" data-preview-settings>Preview</button><button class="primary">Publish homepage</button></div><div class="form-error" role="alert"></div></form>`}
return `<div class="layout"><div class="admin-shell"><aside class="admin-nav" aria-label="Admin navigation">${adminSections.map(t=>{const slug=t.toLowerCase().replaceAll(' ','-');return `<a href="/admin/${slug}" class="${slug===section?'active':''}">${t}</a>`}).join('')}<a href="/tools">Public tools ↗</a><a href="/">Back to How2 ↗</a></aside><section class="admin-main">${content||notFound()}</section></div></div>`}
function adminTable(items,kind){return `<div class="table-wrap"><table><thead><tr><th>ID / title</th><th>${kind==='categories'?'Visibility':'Status'}</th><th>Action</th></tr></thead><tbody>${items.map(x=>`<tr><td><span class="muted">#${x.id}</span> ${esc(x.title||x.name)}</td><td><span class="badge">${esc(x.status||(x.visible?'Visible':'Hidden'))}</span></td><td><a class="text-link" href="/admin/${kind}/${x.id}">Edit ↗</a></td></tr>`).join('')}</tbody></table></div>`}
function editor(kind,id){if(!S.admin)return adminPage();const a=S.admin,x=id==='new'?{}:a[kind]?.find(x=>x.id===Number(id));if(!x)return notFound();let fields='';
if(kind==='lessons')fields=`${field('Lesson title','title','text',x.title||'','required')}<label class="field">Category<select name="category_id">${a.categories.map(c=>`<option value="${c.id}" ${c.id===x.category_id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label class="field">Difficulty<select name="difficulty">${['Beginner','Intermediate','Advanced'].map(d=>`<option ${x.difficulty===d?'selected':''}>${d}</option>`).join('')}</select></label>${field('Estimated completion time (minutes)','minutes','number',x.minutes||5,'required min="1" max="180"')}<label class="field wide">Short description<textarea name="description" required>${esc(x.description||'')}</textarea></label><div class="wide"><label class="field">Lesson content</label><div class="toolbar"><button type="button" data-insert="heading">Heading</button><button type="button" data-insert="bold">Bold</button><button type="button" data-insert="step">Numbered step</button><button type="button" data-insert="bullet">Bullet list</button><button type="button" data-insert="link">Link</button><button type="button" data-insert="image">Image</button><button type="button" data-insert="video">Video</button></div><label class="field"><span class="muted">Use the toolbar to add formatting, links, images, and reviewed videos. Replace example addresses before publishing. Videos use youtube-nocookie.com/embed/ addresses.</span><textarea name="content" id="content-editor" style="min-height:300px" required>${esc(x.content||'## Quick explanation\n\n## Why it matters\n\n## Step by step\n\n1. ')}</textarea></label></div><label class="field wide">Real-life example<textarea name="example">${esc(x.example||'')}</textarea></label><div class="wide"><label class="field">Quiz questions<textarea name="quiz" hidden>${esc(x.quiz||'[]')}</textarea></label><button class="secondary" type="button" data-add-quiz>+ Add quiz question</button><p class="muted">Add questions, write the answer options, and select the correct answer.</p></div>${field('Search keywords','keywords','text',x.keywords||'')}${field('Content date','review_date','date',x.review_date||'')}<label class="field wide">Reference URLs (one per line)<textarea name="sources">${esc(x.sources||'')}</textarea></label><label class="check-row wide"><input name="needs_review" type="checkbox" ${x.needs_review!==0?'checked':''}> Needs editorial review (do not claim expert review without evidence)</label>`;
if(kind==='categories')fields=`${field('Category name','name','text',x.name||'','required')}<label class="field">Icon<select name="icon">${['wallet','chef','home','car','shield','briefcase','learn','tools'].map(i=>`<option ${i===x.icon?'selected':''}>${i}</option>`).join('')}</select></label><label class="field wide">Description<textarea name="description" required>${esc(x.description||'')}</textarea></label>${field('Accent color','color','color',x.color||'#e9e5ff')}${field('Display order','position','number',x.position||0,'required')}<label class="check-row wide"><input type="checkbox" name="visible" ${x.visible!==0?'checked':''}> Visible (uncheck to hide or archive this category)</label>`;
if(kind==='recipes')fields=recipeEditor(x);
if(kind==='paths')fields=`${field('Path name','name','text',x.name||'','required')}<label class="field">Status<select name="status">${['draft','published','archived'].map(s=>`<option ${s===x.status?'selected':''}>${s}</option>`).join('')}</select></label><label class="field wide">Description<textarea name="description" required>${esc(x.description||'')}</textarea></label><label class="field wide">Lessons in learning order<textarea name="lessons" hidden>${esc(x.lessons||'[]')}</textarea></label><div class="wide"><p class="muted">Select lessons and arrange the steps in your learning path.</p></div>`;
return `<div class="layout"><div class="reader"><a href="/admin/${kind==='paths'?'learning-paths':kind==='recipes'?'tools':kind}" class="text-link">← Back to ${kind}</a><h1>${id==='new'?'Create':'Edit'} ${kind==='lessons'?'lesson':kind==='categories'?'category':kind==='recipes'?'recipe':'learning path'}</h1><form id="editor-form" class="panel" data-kind="${kind}" data-id="${x.id||''}"><div class="form-grid">${fields}</div><div class="form-error" role="alert"></div><div class="flex">${kind==='lessons'?'<button class="secondary" type="submit" data-status="draft">Save draft</button><button class="secondary" type="button" data-preview-lesson>Preview</button><button class="primary" type="submit" data-status="published">Publish</button>':'<button class="primary" type="submit">Save changes</button>'}<a class="secondary" href="/admin/${kind==='paths'?'learning-paths':kind==='recipes'?'tools':kind}">Cancel</a>${x.id&&kind!=='categories'&&kind!=='recipes'?'<button class="secondary" type="submit" data-status="archived">Archive</button>':''}</div></form></div></div>`}
function formData(form){return Object.fromEntries(new FormData(form))}
function modal(content){$('#modal').innerHTML=`<button class="icon-btn close" data-close aria-label="Close dialog">✕</button>${content}`;$('#modal').showModal()}
async function render(){const version=++renderVersion;chrome();const path=location.pathname,parts=path.split('/').filter(Boolean);let content='';if(parts[0]==='admin'&&parts[1]!=='login'&&S.user&&['owner','content'].includes(S.user.role)){try{S.admin=await api('admin')}catch(e){toast(e.message)}if(version!==renderVersion)return}
if(path==='/')content=home();else if(path==='/learn'||parts[0]==='category')content=libraryPage(parts[0]==='category'?Number(parts[1]):null);else if(parts[0]==='lesson')content=lessonPage(Number(parts[1]));else if(path==='/saved')content=savedPage();else if(path==='/progress')content=progressPage();else if(path==='/tools')content=toolsPage();else if(path==='/login'||path==='/signup')content=loginPage(path==='/signup');else if(path==='/onboarding')content=onboarding();else if(path==='/profile')content=profilePage();else if(path==='/suggest')content=feedbackPage();else if(path==='/admin/login')content=loginPage(false,true);else if(parts[0]==='admin'){content=parts.length===3&&['lessons','categories','paths','recipes'].includes(parts[1])?editor(parts[1],parts[2]):adminPage(parts[1]||'dashboard')}else if(info[parts[0]])content=infoPage(parts[0]);else content=notFound();$('#main').innerHTML=content.replaceAll('↗',icon('arrow'));document.title=($('#main h1')?.textContent||'Life, figured out.')+' — How2';if($('#results'))filterLessons();document.querySelectorAll('.calc').forEach(calculate);quizBuilder();pathBuilder();if(new URLSearchParams(location.search).get('focus')==='search')$('#search')?.focus();
if(parts[0]==='lesson'&&S.user){const id=Number(parts[1]);if(S.lessons.some(l=>l.id===id)&&!S.progress.some(p=>p.lesson_id===id)){try{await api(`lesson/${id}/progress`,'POST',{completed:false});const l=await api('library');S.progress=l.progress}catch(e){toast(e.message)}}}}
document.addEventListener('click',async e=>{const a=e.target.closest('a');if(a&&a.origin===location.origin&&a.target!=='_blank'&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&a.getAttribute('href')?.startsWith('/')){e.preventDefault();go(a.pathname+a.search);return}const b=e.target.closest('button');if(!b)return;try{
if(b.hasAttribute('data-close'))$('#modal').close();
if(b.dataset.save){if(!S.user){go('/login');toast('Sign in to save your lessons.');return}const id=Number(b.dataset.save);await api(`lesson/${id}/save`,'POST',{saved:!S.saved.includes(id)});await refresh();render()}
if(b.dataset.complete){if(!S.user){go('/login');toast('Sign in to keep your progress.');return}await api(`lesson/${b.dataset.complete}/progress`,'POST',{completed:b.dataset.done!=='true'});await refresh();render();toast(b.dataset.done==='true'?'Lesson marked incomplete.':'One more skill in your toolkit. Lesson complete!')}
if(b.dataset.path){await api('path/'+b.dataset.path,'POST',{state:b.dataset.state});await refresh();render()}
if(b.hasAttribute('data-logout')){await api('logout','POST',{});S.user=null;const s=await api('session');S.csrf=s.csrf;await refresh();go('/')}
if(b.hasAttribute('data-delete-account'))modal(`<h2>Delete your account?</h2><p>This permanently removes your account, saved lessons, and progress.</p><form id="delete-form">${field('Confirm your current password','current_password','password','','required')}<button class="primary">Delete my account</button><div class="form-error" role="alert"></div></form>`);
if(b.dataset.insert){const el=$('#content-editor'),v={heading:'\n\n## New heading\n',bold:'**important text**',step:'\n\n1. Your next step.',bullet:'\n\n- First item\n- Second item',link:'[Link text](https://example.com)',image:'![Describe the image](https://example.com/image.jpg)',video:'\n\n@video https://www.youtube-nocookie.com/embed/VIDEO_ID'}[b.dataset.insert];el.setRangeText(v,el.selectionStart,el.selectionEnd,'end');el.focus()}
if(b.hasAttribute('data-add-quiz')){const el=$('[name="quiz"]');let qs;try{qs=JSON.parse(el.value)}catch{throw Error('Correct the existing quiz JSON first.')}qs.push({question:'Your question',options:['First option','Second option'],answer:0,explanation:'Explain why this answer is correct.'});el.value=JSON.stringify(qs,null,2)}
if(b.hasAttribute('data-preview-lesson')){const d=formData($('#editor-form'));modal(`<span class="eyebrow">UNPUBLISHED PREVIEW</span><h2>${esc(d.title)}</h2><p>${esc(d.description)}</p>${formatContent(d.content)}<div class="example">${esc(d.example)}</div>`)}
if(b.hasAttribute('data-preview-settings')){const d=formData($('#settings-form'));modal(`<span class="eyebrow">HOMEPAGE PREVIEW</span><h2>${esc(d.headline)}</h2><p>${esc(d.description)}</p>${d.announcement?`<p class="notice">${esc(d.announcement)}</p>`:''}<p>Featured lesson IDs: ${esc(new FormData($('#settings-form')).getAll('featured').join(', '))}</p><p>Primary color: ${esc(d.primary)}</p>`)}
}catch(err){toast(err.message)}});
document.addEventListener('input',e=>{if(e.target.closest('.calc'))calculate(e.target.closest('.calc'));if(e.target.id==='search'&&$('#results'))filterLessons()});
document.addEventListener('change',async e=>{if(e.target.closest('.filters'))filterLessons();try{if(e.target.dataset.feedback){await api('admin/feedback','POST',{id:Number(e.target.dataset.feedback),status:e.target.value});toast('Feedback updated.')}if(e.target.dataset.role){if(!confirm('Change this account’s permissions?')){render();return}await api('admin/users','POST',{id:Number(e.target.dataset.role),role:e.target.value});toast('Permissions updated.')}}catch(err){toast(err.message);render()}});
document.addEventListener('submit',async e=>{const f=e.target;if(!(f instanceof HTMLFormElement))return;e.preventDefault();const errBox=f.querySelector('.form-error');if(errBox)errBox.innerHTML='';try{
if(f.id==='search-form'){if($('#results')){filterLessons();history.replaceState({},'','/learn?q='+encodeURIComponent($('#search').value))}else go('/learn?q='+encodeURIComponent($('#search').value));return}
if(f.classList.contains('calc'))return;
if(f.classList.contains('quiz')){const l=S.lessons.find(l=>l.id===Number(f.dataset.lesson)),q=JSON.parse(l.quiz)[Number(f.dataset.quiz)],answer=Number(new FormData(f).get('answer'));f.querySelector('output').textContent=(answer===q.answer?'That’s right! ':'Not quite. ')+q.explanation;return}
const d=formData(f);
if(f.id==='auth-form'){const s=await api('auth/'+f.dataset.mode,'POST',d);S.user=s.user;S.csrf=s.csrf;await refresh();if(f.dataset.admin==='true'&&!['owner','content'].includes(S.user.role)){go('/');toast('Signed in as a learner. Administrator permission is required for the dashboard.')}else go(f.dataset.admin==='true'?'/admin':f.dataset.mode==='signup'?'/onboarding':'/progress')}
if(f.id==='feedback-form'){d.lesson_id=d.lesson_id?Number(d.lesson_id):null;await api('feedback','POST',d);f.reset();toast('Thank you. Your message is in the admin feedback inbox.')}
if(f.id==='onboarding-form'){if(S.user){await api('profile','PUT',{preferences:d});const s=await api('session');S.user=s.user}go('/category/'+d.interest);toast(S.user?'Your preferences have been saved.':'Here’s a place to start. Sign up if you’d like to keep your preferences.')}
if(f.id==='profile-form'||f.id==='password-form'){await api('profile','PUT',d);const s=await api('session');S.user=s.user;toast('Account updated.');render()}
if(f.id==='delete-form'){await api('profile','DELETE',d);$('#modal').close();S.user=null;const s=await api('session');S.csrf=s.csrf;await refresh();go('/');toast('Your account and learning records have been deleted.')}
if(f.id==='settings-form'){d.featured=new FormData(f).getAll('featured').map(Number);d.recommended_paths=new FormData(f).getAll('recommended_paths').map(Number);if(d.image_url&&!safeURL(d.image_url))throw Error('Use a valid HTTPS image address.');if(d.image_url&&!d.image_alt.trim())throw Error('Describe the image for screen readers.');if(d.featured.some(id=>!S.admin.lessons.some(l=>l.id===id&&l.status==='published')))throw Error('Featured IDs must refer to published lessons.');await api('admin/settings','POST',d);await refresh();toast('Homepage published.');render()}
if(f.id==='editor-form'){const kind=f.dataset.kind;if(f.dataset.id)d.id=Number(f.dataset.id);if(kind==='lessons'){d.category_id=Number(d.category_id);d.minutes=Number(d.minutes);d.needs_review=f.elements.needs_review.checked?1:0;d.status=e.submitter?.dataset.status||'draft';JSON.parse(d.quiz)}if(kind==='recipes')d.reviewed=f.elements.reviewed.checked?1:0;if(kind==='categories'){d.position=Number(d.position);d.visible=f.elements.visible.checked?1:0}if(kind==='paths'&&e.submitter?.dataset.status)d.status=e.submitter.dataset.status;if(d.status==='archived'&&!confirm('Archive this content? It will be hidden publicly and can be restored from this editor.'))return;await api('admin/'+kind,'POST',d);await refresh();toast(d.status==='published'?'Published. Your changes are live.':'Changes saved.');go('/admin/'+(kind==='paths'?'learning-paths':kind==='recipes'?'tools':kind))}
}catch(err){if(errBox)errBox.innerHTML=`<p class="error">${esc(err.message)}</p>`;else toast(err.message)}});
window.addEventListener('popstate',render);
(async()=>{try{const s=await api('session');S.user=s.user;S.csrf=s.csrf;await refresh();await render()}catch(e){$('#main').innerHTML=`<div class="empty"><h1>We couldn't load How2.</h1><p>${esc(e.message)}</p><a class="button" href="/">Try again</a></div>`}})();
function quizBuilder(){const store=$('#editor-form [name="quiz"]');if(!store)return;let qs=[];try{qs=JSON.parse(store.value)}catch{}let holder=$('#quiz-builder');if(!holder){holder=document.createElement('div');holder.id='quiz-builder';store.after(holder)}holder.innerHTML=qs.map((q,i)=>`<section class="quiz" data-question="${i}"><label class="field">Question ${i+1}<input data-qfield="question" value="${esc(q.question)}" required></label>${q.options.map((o,j)=>`<label class="field">Answer option ${j+1}<input data-qoption="${j}" value="${esc(o)}" required></label>`).join('')}<label class="field">Correct answer<select data-qfield="answer">${q.options.map((o,j)=>`<option value="${j}" ${j===q.answer?'selected':''}>Option ${j+1}</option>`).join('')}</select></label><label class="field">Answer explanation<textarea data-qfield="explanation" required>${esc(q.explanation)}</textarea></label><button class="secondary" type="button" data-remove-question="${i}">Remove question</button></section>`).join('')}
function pathBuilder(){const store=$('#editor-form [name="lessons"]');if(!store)return;let ids=[];try{ids=JSON.parse(store.value)}catch{}let holder=$('#path-builder');if(!holder){holder=document.createElement('div');holder.id='path-builder';store.after(holder)}holder.innerHTML=`<label class="field">Add a lesson<select id="path-lesson-select">${S.admin.lessons.filter(l=>!ids.includes(l.id)).map(l=>`<option value="${l.id}">${esc(l.title)} (${esc(l.status)})</option>`).join('')}</select></label><button type="button" class="secondary" data-add-path-lesson>Add selected lesson</button><ol>${ids.map((id,i)=>`<li class="path"><p>${esc(S.admin.lessons.find(l=>l.id===id)?.title||'Unavailable lesson')}</p><div class="flex"><button class="secondary" type="button" data-move-lesson="${i}" data-dir="-1" ${i===0?'disabled':''}>Move up</button><button class="secondary" type="button" data-move-lesson="${i}" data-dir="1" ${i===ids.length-1?'disabled':''}>Move down</button><button class="secondary" type="button" data-remove-lesson="${i}">Remove</button></div></li>`).join('')}</ol>`}
document.addEventListener('input',e=>{const question=e.target.closest('[data-question]');if(!question)return;const store=$('[name="quiz"]');let qs=JSON.parse(store.value);const q=qs[Number(question.dataset.question)];if(e.target.dataset.qfield){const field=e.target.dataset.qfield;q[field]=field==='answer'?Number(e.target.value):e.target.value}if(e.target.dataset.qoption!==undefined)q.options[Number(e.target.dataset.qoption)]=e.target.value;store.value=JSON.stringify(qs)});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.removeQuestion!==undefined){const store=$('[name="quiz"]');const qs=JSON.parse(store.value);qs.splice(Number(b.dataset.removeQuestion),1);store.value=JSON.stringify(qs);quizBuilder()}if(b.hasAttribute('data-add-quiz'))quizBuilder();if(b.hasAttribute('data-add-path-lesson')||b.dataset.moveLesson!==undefined||b.dataset.removeLesson!==undefined){const store=$('[name="lessons"]'),ids=JSON.parse(store.value);if(b.hasAttribute('data-add-path-lesson')){const id=Number($('#path-lesson-select').value);if(id&&!ids.includes(id))ids.push(id)}if(b.dataset.removeLesson!==undefined)ids.splice(Number(b.dataset.removeLesson),1);if(b.dataset.moveLesson!==undefined){const i=Number(b.dataset.moveLesson),j=i+Number(b.dataset.dir);if(j>=0&&j<ids.length)[ids[i],ids[j]]=[ids[j],ids[i]]}store.value=JSON.stringify(ids);pathBuilder()}});
function mealPlanner(){return `<form id="meal-planner" class="panel mb"><h2>Beginner meal planner</h2><p class="muted">Build a plan from recipes published as reviewed by your administrators. Your budget sets a spending allowance, not an estimate of grocery prices. Check local prices and food labels.</p><div class="form-grid">${field('Weekly food budget ($)','budget','number','50','required min="0.01" step="0.01"')}${field('Number of meals','meals','number','7','required min="1" max="21"')}<label class="field">Dietary preference<select name="dietary"><option value="any">No restriction</option><option value="vegetarian">Vegetarian</option><option value="vegan">Vegan</option></select></label></div><button class="primary">Plan my meals</button><div id="meal-results" aria-live="polite"></div></form>`}
function recipeEditor(x={}){return `${field('Recipe name','name','text',x.name||'','required')}<label class="field">Dietary classification<select name="dietary">${['vegetarian','vegan','no restriction'].map(v=>`<option ${v===x.dietary?'selected':''}>${v}</option>`).join('')}</select></label><label class="field wide">Ingredients, portions, and allergen notes<textarea name="ingredients" required>${esc(x.ingredients||'')}</textarea></label><label class="field wide">Complete cooking and food safety instructions<textarea name="instructions" required>${esc(x.instructions||'')}</textarea></label>${field('Reliable reference URL','source','url',x.source||'','required')}${field('Review date','review_date','date',x.review_date||'')}<label class="check-row wide"><input type="checkbox" name="reviewed" ${x.reviewed?'checked':''}> I have reviewed this recipe, including food safety and dietary classification. Publish it for meal planning.</label><p class="muted wide">Do not mark a recipe reviewed without completing an actual review. Uncheck to remove it from public meal planning.</p>`}
document.addEventListener('submit',e=>{if(e.target.id!=='meal-planner')return;e.preventDefault();const d=formData(e.target),n=Number(d.meals),budget=Number(d.budget);if(!Number.isInteger(n)||n<1||n>21||!Number.isFinite(budget)||budget<=0)return;const recipes=(S.recipes||[]).filter(r=>d.dietary==='any'||r.dietary===d.dietary||(d.dietary==='vegetarian'&&r.dietary==='vegan'));$('#meal-results').innerHTML=recipes.length?`<p class="result">Spending allowance: <strong>${(budget/n).toLocaleString('en-US',{style:'currency',currency:'USD'})} per meal</strong>Actual ingredient costs may be higher or lower. Repeated meals are included when your plan is longer than the recipe collection.</p>${Array.from({length:n},(_,i)=>{const r=recipes[i%recipes.length];return `<details class="path"><summary>Meal ${i+1}: ${esc(r.name)}</summary><h3>Ingredients & notes</h3><p>${esc(r.ingredients).replace(/\n/g,'<br>')}</p><h3>Instructions</h3>${formatContent(r.instructions)}<p class="muted">Admin-reviewed: ${esc(r.review_date)} · ${esc(r.dietary)}<br><a href="${esc(safeURL(r.source)||'#')}" target="_blank" rel="noopener noreferrer">Recipe reference</a></p></details>`}).join('')}`:'<p class="empty">No reviewed recipes match this preference yet. Administrators can add and review recipes under Admin → Tools. In the meantime, explore the written cooking guide.</p>'});
function recommendedPaths(){const selected=(S.settings.recommended_paths||[]).map(id=>S.paths.find(p=>p.id===id)).filter(Boolean);return selected.length?`<section class="section"><h2>A path to your next chapter</h2>${selected.map(p=>`<article class="path"><h3>${esc(p.name)}</h3><p class="muted">${esc(p.description)}</p><a href="/progress" class="text-link">Explore this learning path →</a></article>`).join('')}</section>`:''}
